        async function testConnection() {
            const cfg = getGhConfig();
            if (!ghConfigComplete(cfg)) {
                setSyncStatus('⚠️ Jeton, utilisateur et dépôt requis', 'warn');
                return;
            }
            setSyncStatus('⏳ Test en cours…', 'busy');
            try {
                const res = await fetch(`https://api.github.com/repos/${encodeURIComponent(cfg.owner)}/${encodeURIComponent(cfg.repo)}`, {
                    headers: {
                        'Authorization': `Bearer ${cfg.token}`,
                        'Accept': 'application/vnd.github+json'
                    }
                });
                if (res.ok) {
                    setSyncStatus('✓ Connexion au dépôt réussie', 'ok');
                } else if (res.status === 404) {
                    setSyncStatus('✗ Dépôt introuvable ou jeton sans accès', 'error');
                } else if (res.status === 401) {
                    setSyncStatus('✗ Jeton invalide', 'error');
                } else {
                    setSyncStatus(`✗ Erreur (${res.status})`, 'error');
                }
            } catch (err) {
                setSyncStatus('✗ Erreur réseau : ' + err.message, 'error');
            }
        }
        // -------------------------------------------------------------
        // ENCODAGE BASE64 UTF-8
        // -------------------------------------------------------------
        function b64EncodeUnicode(str) {
            return btoa(unescape(encodeURIComponent(str)));
        }
        function b64DecodeUnicode(str) {
            return decodeURIComponent(escape(atob(str)));
        }
